contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(address from, address[] memory tos, uint v) public {
        require(tos.length > 0);
        // This test contract itself acts as the token: its fallback answers
        // transferFrom with success, so the deciding call must succeed.
        bool ok = c.transfer(from, address(this), tos, v);
        assert(ok == true);
    }

    fallback(bytes calldata input) external returns (bytes memory) {
        if (input.length >= 4) {
            require(bytes4(input[:4]) == bytes4(keccak256("transferFrom(address,address,uint256)")));
        }
        return abi.encode(true);
    }

    receive() external payable {}
}

