contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(address from, uint v, uint n) public {
        require(n > 1 && n < 5);
        address[] memory tos = new address[](n);
        for (uint i = 0; i < n; i++) {
            tos[i] = address(uint160(i + 1));
        }
        bool reverted;
        bool ret;
        try c.transfer(from, address(this), tos, v) returns (bool r) {
            reverted = false;
            ret = r;
        } catch {
            reverted = true;
        }
        assert(!reverted && ret);
    }

    fallback(bytes calldata) external returns (bytes memory) {
        return abi.encode(true);
    }

    receive() external payable {}
}

