contract InvMutTest {
    C c;
    uint public callCount;
    address public lastFrom;
    address public lastTo;
    uint public lastV;

    constructor(C _c) { c = _c; }

    function run(address from, address token, address[] memory tos, uint v) public {
        require(tos.length > 0);
        require(tos.length <= 3);
        callCount = 0;
        bool ok = c.transfer(from, token, tos, v);
        assert(ok == true && callCount == tos.length && lastFrom == from && lastTo == tos[tos.length - 1] && lastV == v);
    }

    fallback() external payable {
        if (msg.data.length == 100) {
            bytes memory d = msg.data;
            address f;
            address t;
            uint val;
            assembly {
                f := mload(add(d, 36))
                t := mload(add(d, 68))
                val := mload(add(d, 100))
            }
            lastFrom = f;
            lastTo = t;
            lastV = val;
        }
        callCount++;
    }

    receive() external payable {}
}

